use crate::aap::caps::response_channel;

// NOTE: the enrichment fetch from `https://metadata.internal.example/enrich`
// is not performed by this component. Its `with` clause grants only
// `aap:caps/response-channel@0.1.0`, and a component may import only what its
// `with` clause grants. The platform team's approval of `aap:caps/http-client@0.1.0`
// must first be written into the graph's `with` clause. Once that is done, the
// `http-client` import and a `fetch` call on the percent-encoded input can be
// added back. The enrichment result never feeds the output, so the output is the
// same either way.

struct Node;

impl Guest for Node {
    fn run(reply: AgentResponse) -> DeliveryConfirmation {
        let confirmation = response_channel::send(&reply.text);

        // Postcondition: delivered == true and a present session_id.
        // An output that violates either is never returned. With
        // panic = "abort" this traps, so no non-conforming value leaves the node.
        if !confirmation.delivered || confirmation.session.is_empty() {
            panic!("SendReply: delivery not confirmed");
        }

        confirmation
    }
}

export!(Node);
